import os, oracledb
from dotenv import load_dotenv
load_dotenv()
c=oracledb.connect(user=os.getenv("ORACLE_USER","SMARTFOOD_NEW"),password=os.getenv("ORACLE_PASSWORD","CHANGE_ME"),host=os.getenv("ORACLE_HOST","localhost"),port=int(os.getenv("ORACLE_PORT","1521")),service_name=os.getenv("ORACLE_SERVICE","FREEPDB1"))
cur=c.cursor()
ddl=[
"""CREATE TABLE customers(customer_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,full_name VARCHAR2(120) NOT NULL,email VARCHAR2(180) UNIQUE NOT NULL,password_hash VARCHAR2(300) NOT NULL,phone VARCHAR2(30),address VARCHAR2(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)""",
"""CREATE TABLE restaurants(restaurant_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,restaurant_name VARCHAR2(160) NOT NULL,address VARCHAR2(400),latitude NUMBER(10,7),longitude NUMBER(10,7),is_active CHAR(1) DEFAULT 'Y')""",
"""CREATE TABLE menu_items(item_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,restaurant_id NUMBER NOT NULL REFERENCES restaurants(restaurant_id),item_name VARCHAR2(160) NOT NULL,description VARCHAR2(500),price NUMBER(10,2) NOT NULL,is_available CHAR(1) DEFAULT 'Y')""",
"""CREATE TABLE delivery_staff(staff_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,staff_name VARCHAR2(120) NOT NULL,email VARCHAR2(180) UNIQUE NOT NULL,password_hash VARCHAR2(300) NOT NULL,phone VARCHAR2(30),staff_status VARCHAR2(30) DEFAULT 'AVAILABLE')""",
"""CREATE TABLE food_orders(order_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id NUMBER NOT NULL REFERENCES customers(customer_id),order_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,order_status VARCHAR2(30) DEFAULT 'PLACED',total_amount NUMBER(10,2) NOT NULL,delivery_address VARCHAR2(500),delivery_latitude NUMBER(10,7),delivery_longitude NUMBER(10,7))""",
"""CREATE TABLE order_items(order_item_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id NUMBER NOT NULL REFERENCES food_orders(order_id),item_id NUMBER NOT NULL REFERENCES menu_items(item_id),quantity NUMBER(5) NOT NULL,unit_price NUMBER(10,2) NOT NULL)""",
"""CREATE TABLE deliveries(delivery_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id NUMBER NOT NULL UNIQUE REFERENCES food_orders(order_id),staff_id NUMBER REFERENCES delivery_staff(staff_id),delivery_status VARCHAR2(30) DEFAULT 'PENDING',delivered_at TIMESTAMP)""",
"""CREATE TABLE order_status_history(history_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id NUMBER NOT NULL REFERENCES food_orders(order_id),old_status VARCHAR2(30),new_status VARCHAR2(30),changed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)""",
"""CREATE TABLE delivery_locations(order_id NUMBER PRIMARY KEY REFERENCES food_orders(order_id),staff_id NUMBER REFERENCES delivery_staff(staff_id),latitude NUMBER(10,7) NOT NULL,longitude NUMBER(10,7) NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)"""
]
for sql in ddl:
    try: cur.execute(sql); print("Created",sql.split("(")[0].replace("CREATE TABLE ",""))
    except oracledb.DatabaseError as e:
        if "ORA-00955" in str(e): print("Already exists:",sql.split("(")[0])
        else: raise
# Non-destructive migrations for schemas created by earlier project versions.
for sql, label in [
    ("ALTER TABLE food_orders ADD (delivery_latitude NUMBER(10,7))", "food_orders.delivery_latitude"),
    ("ALTER TABLE food_orders ADD (delivery_longitude NUMBER(10,7))", "food_orders.delivery_longitude"),
]:
    try:
        cur.execute(sql)
        print("Added column:", label)
    except oracledb.DatabaseError as e:
        if "ORA-01430" in str(e):
            print("Column already exists:", label)
        else:
            raise
# Safe seed: only insert demo restaurant/menu/staff if absent
cur.execute("SELECT COUNT(*) FROM restaurants")
if cur.fetchone()[0]==0:
    cur.execute("INSERT INTO restaurants(restaurant_name,address,latitude,longitude) VALUES('SmartBite Restaurant','Kharar, Punjab, India',30.749611,76.629417)")
    cur.execute("SELECT restaurant_id FROM restaurants WHERE restaurant_name='SmartBite Restaurant'"); rid=cur.fetchone()[0]
    for n,d,p in [("Assamese Thali","Traditional Assamese meal",180),("Paneer Butter Masala","Paneer in creamy tomato gravy",220),("Veg Fried Rice","Wok-tossed rice and vegetables",140),("Chicken Biryani","Aromatic rice with chicken",240)]:
        cur.execute("INSERT INTO menu_items(restaurant_id,item_name,description,price) VALUES(:r,:n,:d,:p)",{"r":rid,"n":n,"d":d,"p":p})
cur.execute("SELECT COUNT(*) FROM delivery_staff WHERE LOWER(email)='delivery@smartfood.local'")
if cur.fetchone()[0]==0:
    cur.execute("INSERT INTO delivery_staff(staff_name,email,password_hash,phone,staff_status) VALUES('Demo Delivery Staff','delivery@smartfood.local','Delivery_2026','9876500010','AVAILABLE')")
# Preserve existing restaurant coordinates; only fill missing values with the project default.
# To intentionally change the restaurant location, update the restaurants row in Oracle SQL Developer.
cur.execute("UPDATE restaurants SET restaurant_name=NVL(restaurant_name,'SmartBite Restaurant'), address=NVL(address,'Kharar, Punjab, India'), latitude=NVL(latitude,30.749611), longitude=NVL(longitude,76.629417) WHERE restaurant_id=(SELECT MIN(restaurant_id) FROM restaurants)")
c.commit()
print("Schema checked. Existing restaurant coordinates were preserved; missing coordinates use the Kharar default.")
cur.close(); c.close()
